mapper.select:
SELECT g.total_budget
FROM goal g
INNER JOIN couple c
    ON c.id = g.couple_id
WHERE g.is_main = TRUE
  AND c.status = 'CONNECTED'
  AND (
      c.groom_id = #{userId}
      OR c.bride_id = #{userId}
  )

SELECT sr.record_date AS date, MAX(CASE WHEN sr.type='INCOME' THEN 1 ELSE 0 END) AS hasIncome, MAX(CASE WHEN sr.type='EXPENSE' THEN 1 ELSE 0 END) AS hasExpense, MAX(CASE WHEN sr.type='SAVING' THEN 1 ELSE 0 END) AS hasSaving, COALESCE(SUM(CASE WHEN sr.type = 'EXPENSE' THEN sr.amount ELSE 0 END), 0) AS expense, COALESCE(SUM(CASE WHEN sr.type = 'SAVING' THEN sr.amount ELSE 0 END), 0) AS saving FROM service_record sr INNER JOIN ( SELECT #{userId} AS user_id UNION SELECT CASE WHEN c.groom_id = #{userId} THEN c.bride_id ELSE c.groom_id END FROM couple c WHERE c.status='CONNECTED' AND (c.groom_id=#{userId} OR c.bride_id=#{userId}) ) target_user ON target_user.user_id = sr.user_id WHERE sr.record_date BETWEEN #{start} AND #{end} AND COALESCE(sr.changed_category, sr.category) IN
#{category}
GROUP BY sr.record_date ORDER BY sr.record_date

SELECT sr.id AS recordId, sr.type AS type, CASE WHEN sr.changed_category IS NOT NULL THEN sr.changed_category ELSE sr.category END AS category, sr.amount, sr.memo, u.name AS owner, sr.user_id AS ownerId, CASE WHEN sr.user_id = #{userId} THEN TRUE ELSE FALSE END AS isMine, CASE WHEN sr.account_record_id IS NULL AND sr.card_record_id IS NULL THEN TRUE ELSE FALSE END AS isUserCreated FROM service_record sr INNER JOIN user u ON sr.user_id = u.id INNER JOIN ( SELECT #{userId} AS user_id UNION SELECT CASE WHEN c.groom_id = #{userId} THEN c.bride_id ELSE c.groom_id END FROM couple c WHERE c.status='CONNECTED' AND ( c.groom_id=#{userId} OR c.bride_id=#{userId} ) ) target_user ON target_user.user_id = sr.user_id WHERE sr.record_date = #{date} AND COALESCE(sr.changed_category, sr.category) IN
#{category}
ORDER BY sr.updated_at DESC

mapper.delete:
DELETE
FROM service_record
WHERE id = #{recordId}
  AND user_id = #{userId}
